powershell -Command "$f='C:/Android/Ohrana-c7953c45/app/src/main/java/com/example/ohrana/ShiftDatabaseManager.kt'; $c=[System.IO.File]::ReadAllText($f,$[Text.Encoding]::UTF8); $old=@'
            .mapNotNull { 
                try {
                    val json = JSONObject(it.value as String)
                    ShiftLogEntry(
                        id = json.getString(\"id\"),
                        timestamp = json.getString(\"timestamp\"),
                        checkpointName = json.getString(\"checkpointName\"),
                        checkpointId = json.getString(\"checkpointId\"),
                        employeeName = json.getString(\"employeeName\"),
                        roundId = json.getInt(\"roundId\"),
                        shiftId = json.getString(\"shiftId\"),
                        routeName = json.getString(\"routeName\"),
                        sequenceIndex = json.getInt(\"sequenceIndex\"),
                        isSequenceCorrect = json.getBoolean(\"isSequenceCorrect\"),
                        scanType = json.getString(\"scanType\"),
                        actionType = json.getString(\"actionType\"),
                        questionText = if (json.has(\"questionText\")) json.getString(\"questionText\") else null,
                        inputTitle = if (json.has(\"inputTitle\")) json.getString(\"inputTitle\") else null,
                        answer = if (json.has(\"answer\")) json.getString(\"answer\") else null,
                        inputValue = if (json.has(\"inputValue\")) json.getString(\"inputValue\") else null,
                        photoPath = if (json.has(\"photoPath\")) json.getString(\"photoPath\") else null,
                        latitude = json.optDouble(\"latitude\", Double.NaN).takeIf { !it.isNaN() },
                        longitude = json.optDouble(\"longitude\", Double.NaN).takeIf { !it.isNaN() },
                        sequenceErrorType = try {
                            val seqErrorStr = json.optString(\"sequenceErrorType\", \"NONE\")
                            SequenceErrorType.valueOf(seqErrorStr)
                        } catch (e: Exception) {
                            SequenceErrorType.NONE
                        },
                        hasAborted = json.optBoolean(\"hasAborted\", false)
                    )
                } catch (e: Exception) {
                    null
                }
            }'; $new=@'
            .mapNotNull { (entryKey, entryValue) ->
                @Suppress(\"UNCHECKED_CAST\")
                val json = try { JSONObject(entryValue as String) } catch (e: Exception) { null } ?: return@mapNotNull null
                parseShiftLogEntry(json)
            }'; $c=$c.Replace($old,$new); [System.IO.File]::WriteAllText($f,$c,[Text.Encoding]::UTF8); Write-Host 'Done'"

python -c "
import os
path = r'C:\Android\Ohrana-c7953c45\app\src\main\java\com\example\ohrana\ShiftFileStore.kt'
content = '''package com.example.ohrana

import android.content.Context
import android.util.Log
import java.io.File
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

data class ShiftFileInfo(
    val filePath: String,
    val fileName: String,
    val shiftId: String,
    val date: String?,
    val time: String?,
    val lastModified: Long
)

class ShiftFileStore(private val context: Context) {

    companion object {
        private const val TAG = \"ShiftFileStore\"
        private val dateFormat = SimpleDateFormat(\"dd.MM.yyyy HH:mm:ss\", Locale.US)
        private val dateShortFormat = SimpleDateFormat(\"ddMMyyyy\", Locale.US)
    }

    private fun getShiftDirectory(context: Context): File {
        val downloadDir = context.getExternalFilesDir(null)
            ?: return File(context.getExternalFilesDir(android.os.Environment.DIRECTORY_DOWNLOADS) ?: return emptyList()

        return shiftDir.listFiles()?.filter { it.name.startsWith(\"shift_\") && it.name.endsWith(\".json\") }
            ?.map { file ->
                val shiftInfo = parseDateFromFileName(file.name)
                ShiftFileInfo(
                    filePath = file.absolutePath,
                    fileName = file.name,
                    shiftId = extractShiftIdFromName(file.name),
                    date = shiftInfo?.first,
                    time = shiftInfo?.second,
                    lastModified = file.lastModified()
                )
            }?.sortedByDescending { it.lastModified } ?: emptyList()
    }

    private fun extractShiftIdFromName(fileName: String): String {
        return fileName.removePrefix(\"shift_\")
            .removeSuffix(\".json\")
            .substringBeforeLast(\"_\")
    }

    private fun parseDateFromFileName(fileName: String): Pair<String, String>? {
        val dateStr = fileName.removePrefix(\"shift_\")
            .removeSuffix(\".json\")
            .substringAfterLast(\"_\")

        return try {
            val date = SimpleDateFormat(\"yyyyMMdd\", Locale.US).parse(dateStr)
            if (date != null) {
                val dateString = dateFormat.format(date).substring(0, 10)
                val fullTimeString = dateFormat.format(date)
                Pair(dateString, fullTimeString)
            } else {
                null
            }
        } catch (e: Exception) {
            Log.w(TAG, \"Could not parse date from filename: \" + fileName + \", dateStr=\" + dateStr)
            null
        }
    }

    fun cleanupOldShiftFiles(daysToKeep: Int, context: Context): Int {
        val cutoffDate = Date(System.currentTimeMillis() - daysToKeep * 24L * 60 * 60 * 1000)
        val shiftDir = getShiftDirectory(context)
        var deletedCount = 0

        shiftDir.listFiles()?.filter { it.name.startsWith(\"shift_\") && it.name.endsWith(\".json\") }
            ?.forEach { file ->
                val fileDate = parseDateFromFileName(file.name)?.first
                if (fileDate != null) {
                    try {
                        val parsedDate = dateFormat.parse(fileDate)?.time ?: 0L
                        if (parsedDate < cutoffDate.time) {
                            file.delete()
                            deletedCount++
                            Log.d(TAG, \"Deleted old shift file: \" + file.name)
                        }
                    } catch (e: Exception) {
                        Log.w(TAG, \"Could not parse date for cleanup: \" + file.name)
                    }
                }
            }

        Log.d(TAG, \"Cleanup completed: \" + deletedCount + \" files deleted\")
        return deletedCount
    }
}
'''
with open(path, 'w', encoding='utf-8') as f:
    f.write(content)
print('File created successfully at:', path)
"
